game:GetService("Debris")
game:GetService("ReplicatedStorage")
function t.ApplyTrinket(p1, p2) --[[ ApplyTrinket | Line: 21 ]]
	p2:WaitForChild("Active")
	p1:WaitForChild("Trinkets")

	local Stats = p1:WaitForChild("Stats")

	Stats:WaitForChild("CurrentStamina")
	Stats:WaitForChild("Stamina")
	Stats:WaitForChild("StaminaModifier")
	p1:WaitForChild("Decoding")
	Stats:WaitForChild("StaminaRegenModifier")

	local Active = p2:WaitForChild("Active")

	workspace.Info.Floor.Changed:Connect(function() --[[ Line: 35 | Upvalues: Active (copy) ]]
		if not Active or Active.Parent == nil then
			return
		end

		Active.Value = true
	end)
end
function t.SpecialEvent(p1) --[[ SpecialEvent | Line: 42 ]]
	local HumanoidRootPart = p1:WaitForChild("HumanoidRootPart")

	task.spawn(function() --[[ Line: 45 | Upvalues: p1 (copy), HumanoidRootPart (copy) ]]
		if not p1 or p1.Parent == nil then
			return
